from selfies.utils.smiles_utils import smiles_to_mol
from selfies.utils.matching_utils import find_perfect_matching
from selfies.constants import AROMATIC_VALENCES
import itertools

def prune_free(mol, node):
    # parity-aware free valence
    adj = mol._delocal_subgraph[node]
    if not adj: return True
    atom = mol.get_atom(node)
    valences = AROMATIC_VALENCES[atom.element]
    used_e = int(mol.get_bond_count(node) - 0.5*len(adj))
    if atom.h_count is None:
        return any(used_e == v for v in valences)
    else:
        valence = valences[-1] - atom.charge
        used_e2 = used_e + atom.h_count
        free = valence - used_e2
        if free < 0: return True
        if free % 2 == 0: free += 1  # free-valence term
        return not (free % 2 != 0)

def try_kekulize(smi, use_free):
    mol = smiles_to_mol(smi, attributable=False)
    ds = mol._delocal_subgraph
    fn = (lambda n: prune_free(mol,n)) if use_free else mol._prune_from_ds
    kept = {n for n in ds if not fn(n)}
    rel = {n:i for i,n in enumerate(sorted(kept))}
    pruned=[[] for _ in kept]
    for n in kept:
        for a in ds[n]:
            if a in kept: pruned[rel[n]].append(rel[a])
    m = find_perfect_matching(pruned)
    return m is not None, (sorted(kept) if m is None else None)

for smi in ['c1cc[c+](C)n1','c1cc[nH+]cs1','c1cc[nH]cs1','c1[n]ccs1','[c]1ccccc1','Cc1ccc(NC(=O)c2ccc(-c3[c]n(Br)ccs[nH]3)c(C(F)(F)F)c2)cc1Nc1nccc(-c2cccnc2)n1','c1ccccc1','c1ccncc1','[cH]1ccccc1']:
